import React, { useState } from 'react';
import {
	addMonths,
	calendarStyleKeys,
	getCalendarDayModifiers,
	getCalendarFirstSelectedDate,
	getMonthCaption,
	getMonthGrid,
	getWeekdayLabels,
	selectCalendarDay,
	startOfMonth,
} from '../lib/core';
import type { CalendarBaseProps, CalendarDayModifiers, CalendarSelection } from '../lib/core';
import styles from './calendar.module.scss';

export interface CalendarProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'onSelect'>, CalendarBaseProps {}

export interface CalendarDayButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
	/** 日期 */
	date: Date;
	/** 修饰状态 */
	modifiers: CalendarDayModifiers;
}

/**
 * 单个日期按钮（独立导出，供自定义网格使用）
 */
const CalendarDayButton = React.forwardRef<HTMLButtonElement, CalendarDayButtonProps>(({ date, modifiers, className = '', children, ...props }, ref) => {
	const classes = [styles[calendarStyleKeys.dayButton], className].filter(Boolean).join(' ');

	return (
		<button
			ref={ref}
			type="button"
			data-day={date.toLocaleDateString()}
			data-selected={modifiers.selected}
			data-selected-single={modifiers.selected && !modifiers.rangeStart && !modifiers.rangeEnd && !modifiers.rangeMiddle}
			data-range-start={modifiers.rangeStart}
			data-range-end={modifiers.rangeEnd}
			data-range-middle={modifiers.rangeMiddle}
			data-outside={modifiers.outside}
			data-disabled={modifiers.disabled}
			data-today={modifiers.today}
			disabled={modifiers.disabled}
			aria-disabled={modifiers.disabled}
			className={classes}
			{...props}>
			{children ?? date.getDate()}
		</button>
	);
});
CalendarDayButton.displayName = 'CalendarDayButton';

/**
 * Calendar 日历组件（单选 / 多选 / 范围选择）
 */
const Calendar = React.forwardRef<HTMLDivElement, CalendarProps>(
	({ className = '', mode = 'single', selected, defaultSelected, defaultMonth, showOutsideDays = true, disabled, onSelect, ...props }, ref) => {
		const [internalSelected, setInternalSelected] = useState<CalendarSelection>(defaultSelected);
		const currentSelected = selected !== undefined ? selected : internalSelected;

		const [month, setMonth] = useState<Date>(() => {
			if (defaultMonth) {
				return startOfMonth(defaultMonth);
			}
			const firstSelected = getCalendarFirstSelectedDate(defaultSelected);
			if (firstSelected) {
				return startOfMonth(firstSelected);
			}
			return startOfMonth(new Date());
		});

		function handleSelect(day: Date) {
			if (disabled?.(day)) {
				return;
			}
			const next = selectCalendarDay(mode, currentSelected, day);
			if (selected === undefined) {
				setInternalSelected(next);
			}
			onSelect?.(next);
		}

		const grid = getMonthGrid(month, showOutsideDays);
		const weekdays = getWeekdayLabels();

		return (
			<div ref={ref} data-slot="calendar" data-mode={mode} className={`${styles[calendarStyleKeys.root]} ${className}`} {...props}>
				<div className={styles[calendarStyleKeys.header]}>
					<nav className={styles[calendarStyleKeys.nav]}>
						<button
							type="button"
							aria-label="上个月"
							className={`${styles[calendarStyleKeys.navButton]} ${styles[calendarStyleKeys.navPrev]}`}
							onClick={() => setMonth((prev) => addMonths(prev, -1))}>
							<svg
								className={styles[calendarStyleKeys.icon]}
								xmlns="http://www.w3.org/2000/svg"
								width="24"
								height="24"
								viewBox="0 0 24 24"
								fill="none"
								stroke="currentColor"
								strokeWidth="2"
								strokeLinecap="round"
								strokeLinejoin="round"
								aria-hidden="true">
								<path d="m15 18-6-6 6-6" />
							</svg>
						</button>
						<button
							type="button"
							aria-label="下个月"
							className={`${styles[calendarStyleKeys.navButton]} ${styles[calendarStyleKeys.navNext]}`}
							onClick={() => setMonth((prev) => addMonths(prev, 1))}>
							<svg
								className={styles[calendarStyleKeys.icon]}
								xmlns="http://www.w3.org/2000/svg"
								width="24"
								height="24"
								viewBox="0 0 24 24"
								fill="none"
								stroke="currentColor"
								strokeWidth="2"
								strokeLinecap="round"
								strokeLinejoin="round"
								aria-hidden="true">
								<path d="m9 18 6-6-6-6" />
							</svg>
						</button>
					</nav>
					<div className={styles[calendarStyleKeys.monthCaption]}>{getMonthCaption(month)}</div>
				</div>
				<div className={styles[calendarStyleKeys.weekdays]}>
					{weekdays.map((label) => (
						<div key={label} className={styles[calendarStyleKeys.weekday]}>
							{label}
						</div>
					))}
				</div>
				<div className={styles[calendarStyleKeys.weeks]} role="grid">
					{grid.map((week, weekIndex) => (
						<div key={weekIndex} role="row" className={styles[calendarStyleKeys.week]}>
							{week.map((day, dayIndex) => {
								if (!day) {
									return <div key={dayIndex} className={styles[calendarStyleKeys.day]} />;
								}
								const modifiers = getCalendarDayModifiers(day, month, currentSelected, showOutsideDays, disabled);
								return (
									<div key={dayIndex} role="gridcell" aria-selected={modifiers.selected} className={styles[calendarStyleKeys.day]}>
										<CalendarDayButton date={day} modifiers={modifiers} onClick={() => handleSelect(day)} />
									</div>
								);
							})}
						</div>
					))}
				</div>
			</div>
		);
	},
);
Calendar.displayName = 'Calendar';

export { Calendar, CalendarDayButton };
export default Calendar;

@use '../../../styles/variables/colors' as *;

// 日历根容器
.root {
	width: fit-content;
	padding: var(--tile-calendar-padding, $spacing-3);
	background-color: var(--tile-calendar-background, $background);
	border-radius: var(--tile-calendar-radius, $radius-md);
	border: var(--tile-calendar-border, 1px solid $border);
	font-variant-numeric: var(--tile-calendar-numerals, inherit);
}

// 头部（导航 + 月份标题）
.header {
	position: relative;
	height: var(--tile-calendar-header-height, auto);
	display: flex;
	align-items: center;
}

// 上 / 下月导航
.nav {
	display: flex;
	align-items: center;
	justify-content: space-between;
	width: 100%;
	gap: $spacing-1;
}

.navButton {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: var(--tile-calendar-nav-size, 2rem);
	height: var(--tile-calendar-nav-size, 2rem);
	padding: 0;
	border: none;
	border-radius: var(--tile-calendar-day-radius, $radius);
	box-shadow: var(--tile-calendar-nav-shadow, none);
	background-color: transparent;
	color: $foreground;
	cursor: pointer;
	outline: none;
	transition: background-color $transition-fast;

	&:hover:not(:disabled) {
		background-color: var(--tile-calendar-hover-background, $accent);
		color: $accent-foreground;
	}

	&:focus-visible {
		box-shadow: var(--tile-calendar-focus-shadow, 0 0 0 2px $background, 0 0 0 4px $ring);
	}

	&:disabled {
		opacity: 0.5;
		pointer-events: none;
	}

	.icon {
		width: 1rem;
		height: 1rem;
		pointer-events: none;
	}
}

// 月份标题
.monthCaption {
	position: absolute;
	inset-inline: 2rem;
	display: flex;
	align-items: center;
	justify-content: center;
	font-size: $text-sm;
	font-weight: var(--tile-calendar-caption-weight, $font-medium);
	user-select: none;
	pointer-events: none;
}

// 星期表头
.weekdays {
	display: flex;
	width: 100%;
	margin-top: var(--tile-calendar-weekdays-margin, $spacing-2);
}

.weekday {
	flex: 1;
	border-radius: $radius;
	font-size: var(--tile-calendar-weekday-size, 0.8rem);
	font-weight: var(--tile-calendar-weekday-weight, $font-normal);
	color: $muted-foreground;
	text-align: center;
	padding-block: var(--tile-calendar-weekday-padding, $spacing-1);
	user-select: none;
}

// 日期网格
.weeks {
	display: flex;
	flex-direction: column;
	gap: var(--tile-calendar-weeks-gap, $spacing-1);
	margin-top: var(--tile-calendar-weeks-margin, $spacing-1);
}

.week {
	display: flex;
	width: 100%;
}

// 日期单元格
.day {
	flex: 1;
	padding: var(--tile-calendar-cell-padding, 0);
	display: flex;
	align-items: center;
	justify-content: center;
}

.dayButton {
	display: flex;
	align-items: center;
	justify-content: center;
	width: 2rem;
	height: 2rem;
	min-width: 2rem;
	padding: 0;
	border: none;
	border-radius: var(--tile-calendar-day-radius, $radius);
	background-color: transparent;
	color: $foreground;
	font-size: var(--tile-calendar-day-size, $text-sm);
	font-weight: $font-normal;
	line-height: 1;
	text-align: center;
	cursor: pointer;
	outline: none;
	transition:
		background-color $transition-fast,
		color $transition-fast;
	user-select: none;

	&:hover:not(:disabled):not([data-selected='true']) {
		background-color: var(--tile-calendar-hover-background, $accent);
		color: $accent-foreground;
	}

	&:focus-visible {
		box-shadow: var(--tile-calendar-focus-shadow, 0 0 0 2px $background, 0 0 0 4px $ring);
	}

	// 今天
	&[data-today='true'] {
		background-color: var(--tile-calendar-today-background, $accent);
		color: var(--tile-calendar-today-color, $accent-foreground);
		font-weight: var(--tile-calendar-today-weight, $font-normal);

		&[data-selected='true'] {
			background-color: var(--tile-calendar-selected-background, $primary);
			color: var(--tile-calendar-selected-color, $primary-foreground);
		}
	}

	// 相邻月份的天
	&[data-outside='true'] {
		color: $muted-foreground;
		opacity: var(--tile-calendar-outside-opacity, 1);
	}

	// 禁用
	&[data-disabled='true'] {
		color: $muted-foreground;
		opacity: var(--tile-calendar-disabled-opacity, 0.5);
		cursor: not-allowed;
		pointer-events: none;
	}

	// 单选选中态
	&[data-selected-single='true'] {
		background-color: var(--tile-calendar-selected-background, $primary);
		color: var(--tile-calendar-selected-color, $primary-foreground);
	}

	// 范围起点
	&[data-range-start='true'] {
		background-color: var(--tile-calendar-selected-background, $primary);
		color: var(--tile-calendar-selected-color, $primary-foreground);
		border-radius: var(--tile-calendar-day-radius, $radius);
		border-end-end-radius: 0;
		border-start-end-radius: 0;
	}

	// 范围终点
	&[data-range-end='true'] {
		background-color: var(--tile-calendar-selected-background, $primary);
		color: var(--tile-calendar-selected-color, $primary-foreground);
		border-radius: var(--tile-calendar-day-radius, $radius);
		border-start-start-radius: 0;
		border-end-start-radius: 0;
	}

	// 范围中间
	&[data-range-middle='true'] {
		background-color: var(--tile-calendar-range-background, $accent);
		color: var(--tile-calendar-range-color, $accent-foreground);
		border-radius: 0;
	}
}
